CREATE TABLE app.invoices (
  id         bigserial PRIMARY KEY,
  tenant_id  integer NOT NULL,
  amount     numeric(12,2) NOT NULL,
  owner_note text
);

ALTER TABLE app.invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE app.invoices FORCE  ROW LEVEL SECURITY;   -- applies to the owner too

CREATE POLICY tenant_isolation ON app.invoices
  AS PERMISSIVE FOR ALL TO app_rw
  USING      (tenant_id = current_setting('app.tenant_id', true)::integer)
  WITH CHECK (tenant_id = current_setting('app.tenant_id', true)::integer);

-- Support staff may read everything but not write
CREATE POLICY support_read ON app.invoices
  FOR SELECT TO support_ro USING (true);

-- Application pattern, inside every request transaction:
-- BEGIN;
--   SET LOCAL app.tenant_id = '42';
--   SELECT ... ;
-- COMMIT;

